import 'package:zan/Core/Storage/Remote/api_response_model.dart';import '../../../../../Core/Storage/Local/local_storage_keys.dart';import '../../../../../Core/Storage/Local/local_storage_service.dart';import '../entities/login_model.dart';import '../../../../../Core/Storage/Remote/api_endpoints.dart';import '../../../../../Core/Storage/Remote/api_service.dart';import '../entities/register_model.dart';import '../entities/user_data_model.dart';class AuthenticationSources {  static Future<ApiResponseModel<UserDataModel>?> getUserDataByEmail(LoginModel loginModel) async {    final response = await DioHelper.postData(      data: loginModel.toMap(),      path: ApiEndpoints.loginUser,    );    if (response != null && response.statusCode == 200) {      await LocalStorageService.setValue(        LocalStorageKeys.token,        response.data['access_token'],      );      return ApiResponseModel<UserDataModel>(        status: true,        message: "Login Successful",        data: UserDataModel.fromJson(response.data["user"]),      );    }    return ApiResponseModel<UserDataModel>(      status: false,      message: response?.statusMessage ?? "Login Failed",      data: null,    );  }}Future<bool> createAccount(RegisterModel registerModel) async {  final response = await DioHelper.postData(    data:registerModel.toMap() ,    path: ApiEndpoints.registerUser,  );  return  response?.data["status"];}